// 事件分类名称
const EVENT_CATEGORIES = {
  opportunity: '机遇',
  disaster: '灾祸',
  illegitimate: '私生子',
  romance: '情感',
  social: '社交',
  industry: '产业',
  faction: '势力',
  rare: '稀有',
};

// 根据条件筛选可用事件
function filterEvents(events, context) {
  return events.filter(e => {
    if (!e.conditions) return true;
    const c = e.conditions;
    if (c.locations && !c.locations.includes(context.location)) return false;
    if (c.ageMin && context.age < c.ageMin) return false;
    if (c.realmMin && context.realmLevel < c.realmMin) return false;
    if (c.realmMax && context.realmLevel > c.realmMax) return false;
    if (c.faction && context.faction !== c.faction) return false;
    if (c.profession && context.profession !== c.profession) return false;
    if (c.karmaMin && context.karma < c.karmaMin) return false;
    if (c.karmaNegative && context.karma >= 0) return false;
    if (c.favorMin && context.favor < c.favorMin) return false;
    if (c.reputationMin && context.reputation < c.reputationMin) return false;
    if (c.spiritStoneMin && context.spiritStone < c.spiritStoneMin) return false;
    if (c.fateLuckMin && context.fateLuck < c.fateLuckMin) return false;
    if (c.hasResidence && !context.hasResidence) return false;
    if (c.hasField && !context.hasField) return false;
    if (c.hasMine && !context.hasMine) return false;
    if (c.hasShop && !context.hasShop) return false;
    if (c.hasCave && !context.hasCave) return false;
    if (c.hasRanch && !context.hasRanch) return false;
    if (c.hasPet && !context.hasPet) return false;
    if (c.hasSpouse && !context.hasSpouse) return false;
    if (c.single && context.hasSpouse) return false;
    if (c.hasEnemy && !context.hasEnemy) return false;
    if (c.hasIndustry && !context.hasIndustry) return false;
    if (c.officialMin && (context.official || 0) < c.officialMin) return false;
    if (c.positionMin && !checkPosition(context.position, c.positionMin)) return false;
    return true;
  });
}

function checkPosition(current, min) {
  const positions = ['外门', '内门', '真传', '首席', '长老'];
  return positions.indexOf(current) >= positions.indexOf(min);
}

// 随机选取事件
function pickRandomEvent(category, context) {
  const pool = filterEvents(EVENTS[category] || [], context);
  if (pool.length === 0) return null;
  return pool[Math.floor(Math.random() * pool.length)];
}

// 从所有类别中随机选取
function pickAnyRandomEvent(context) {
  const categories = Object.keys(EVENTS);
  const category = categories[Math.floor(Math.random() * categories.length)];
  return pickRandomEvent(category, context);
}

module.exports = { EVENTS, EVENT_CATEGORIES, filterEvents, pickRandomEvent, pickAnyRandomEvent };
